	public ManaReceiver getCollidedTile(boolean noParticles) {
		this.noParticles = noParticles;

		int iterations = 0;
		while (isAlive() && iterations < BotaniaConfig.common().spreaderTraceTime()) {
			tick();
			iterations++;
		}

		if (fake) {
